SELECT luvr.*, lu.name AS userName FROM l_user_visit_record luvr LEFT JOIN l_user lu ON luvr.user_id = lu.id
AND visit_time >= #{startTime}
AND visit_time <= #{endTime}
ORDER BY id DESC LIMIT #{startNum}, #{size}

