    COUNT(id)
FROM
    l_user_visit_record


        AND visit_time >= #{startTime}


        AND visit_time <= #{endTime}

SELECT DATE(FROM_UNIXTIME(visit_time)) AS visit_time, COUNT(DISTINCT CONCAT(user_id, '-', visit_ip)) AS visits FROM l_user_visit_record
AND visit_time >= #{startTime}
AND visit_time <= #{endTime}
GROUP BY DATE(FROM_UNIXTIME(visit_time))
